<template><aside v-if="context" class="agenda-personal" :style="themeStyle" :data-agenda-theme="theme" aria-label="Mi diario personal">
 <button ref="bulb" class="agenda-bulb" :class="{moving:dragging}" :style="bulbStyle" type="button" aria-label="Abrir mi diario personal" :aria-expanded="open?'true':'false'" title="Mi agenda · arrastra el icono para moverlo" @pointerdown="startDrag" @click="toggle"><svg class="agenda-icon" viewBox="0 0 32 32" fill="none" aria-hidden="true"><rect x="5" y="5" width="23" height="24" rx="5" fill="currentColor" opacity=".16"/><rect x="4" y="4" width="23" height="24" rx="5" stroke="currentColor" stroke-width="1.8"/><path d="M10 2v5M21 2v5M4 11h23M10 16h5M10 21h8" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"/><path d="m19 17 2 2 4-4" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/></svg><span v-if="pending.length" class="agenda-count">{{pending.length}}</span></button>
 <section v-if="open" class="agenda-panel" :style="panelStyle" aria-label="Notas de mi diario"><header><div><strong class="agenda-heading"><svg class="agenda-icon" viewBox="0 0 32 32" fill="none" aria-hidden="true"><rect x="5" y="5" width="23" height="24" rx="5" fill="currentColor" opacity=".16"/><rect x="4" y="4" width="23" height="24" rx="5" stroke="currentColor" stroke-width="1.8"/><path d="M10 2v5M21 2v5M4 11h23M10 16h5M10 21h8" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"/><path d="m19 17 2 2 4-4" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/></svg> Mi agenda</strong><small>Solo para ti · @{{context.user}}</small></div><button type="button" @click="dock" title="Guardar la agenda a la derecha" aria-label="Acoplar diario a la derecha">⇥</button><button type="button" @click="open=false" aria-label="Cerrar diario">×</button></header>
  <div class="agenda-day"><div class="agenda-day-heading"><span>{{selectedDay.slice(8,10)}}</span><div><strong>{{selectedDayLabel}}</strong><small>{{dayPending}} {{dayPending===1?'tarea pendiente':'tareas pendientes'}} para este día</small></div></div><div class="agenda-day-controls"><button type="button" @click="moveDay(-1)" :disabled="saving" aria-label="Día anterior">‹</button><input type="date" v-model="selectedDay" :disabled="saving" required aria-label="Fecha de mi agenda"><button type="button" @click="moveDay(1)" :disabled="saving" aria-label="Día siguiente">›</button><button type="button" @click="goToday" :disabled="saving">Hoy</button></div></div><div class="agenda-content"><p v-if="error" class="agenda-error" role="alert">{{error}}</p><p v-if="limited" class="agenda-hint">Se muestran hasta 1000 notas. Conserva tu lista de pendientes al día.</p>
   <form class="agenda-compose" @submit.prevent="save"><small class="agenda-writing-date">{{form.Id?'Editar tarea':'Nueva tarea'}} · {{selectedDayLabel}}</small><input ref="title" v-model="form.Titulo" maxlength="180" required placeholder="¿Qué tienes que hacer?" aria-label="Tarea de mi diario"><textarea v-if="details" v-model="form.Detalle" maxlength="5000" rows="3" placeholder="Escribe tus notas…" aria-label="Detalle de mi nota"></textarea><div class="agenda-dictation"><button type="button" @click="dictate('Titulo')" :disabled="saving" :aria-pressed="dictating==='Titulo'?'true':'false'">🎙 {{dictating==='Titulo'?'Detener dictado':'Dictar tarea'}}</button><button v-if="details" type="button" @click="dictate('Detalle')" :disabled="saving" :aria-pressed="dictating==='Detalle'?'true':'false'">🎙 {{dictating==='Detalle'?'Detener dictado':'Dictar detalle'}}</button></div><p v-if="dictating" class="agenda-listening" role="status">Escuchando en español… {{interim}}</p><p v-if="dictationError" class="agenda-error" role="alert">{{dictationError}}</p><div class="agenda-compose-actions"><button type="button" @click="details=!details">{{details?'Ocultar detalle':'＋ Detalle'}}</button><button type="button" @click="schedule=!schedule">◷ {{form.Recordar?'Editar aviso':'Fecha y aviso'}}</button><button class="agenda-add" type="submit" :disabled="saving||!!dictating">{{saving?'Guardando…':form.Id?'Guardar':'＋ Agregar'}}</button></div>
    <div v-if="schedule" class="agenda-schedule"><label class="agenda-check"><input type="checkbox" v-model="form.Recordar"> Avisarme de esta tarea</label><template v-if="form.Recordar"><label>Fecha y hora · Lima<input type="datetime-local" v-model="form.Fecha" required></label><div class="agenda-two"><label>Avisar antes<select v-model.number="form.Anticipacion"><option :value="0">A la hora indicada</option><option :value="5">5 minutos antes</option><option :value="15">15 minutos antes</option><option :value="30">30 minutos antes</option><option :value="60">1 hora antes</option><option :value="1440">1 día antes</option></select></label><label>Repetir aviso cada<select v-model.number="form.Frecuencia"><option :value="1">1 minuto</option><option :value="5">5 minutos</option><option :value="15">15 minutos</option><option :value="30">30 minutos</option><option :value="60">1 hora</option></select></label></div><label>Repetir la tarea<select v-model="form.Repeticion"><option value="ninguna">Una sola vez</option><option value="diaria">Cada día, al completarla</option><option value="semanal">Cada semana, al completarla</option></select></label><small>Te avisará el pececito aunque cierres este panel. Los avisos se repiten hasta completar la tarea.</small></template></div><button v-if="form.Id" type="button" class="agenda-cancel-edit" @click="reset">Cancelar edición</button>
   </form>
   <nav class="agenda-filters" aria-label="Filtrar mi diario"><button v-for="f in filters" :key="f.id" :class="{active:filter===f.id}" type="button" @click="filter=f.id">{{f.text}}</button><button type="button" @click="load" aria-label="Actualizar diario">↻</button></nav>
   <p v-if="!visible.length" class="agenda-empty">{{loading?'Cargando tu diario…':'Tu lista está libre. Agrega una nota o una tarea.'}}</p>
   <article v-for="note in visible" :key="note.Id" class="agenda-note"><label class="agenda-note-check"><input type="checkbox" :checked="false" :disabled="saving" @change="change(note,'concluir')" :aria-label="'Completar '+note.Titulo"><span><strong>{{note.Titulo}}</strong><small v-if="Number(note.Recordar)">◷ {{dateLabel(note.Fecha)}}{{note.Repeticion==='ninguna'?'':' · '+repeatLabel(note.Repeticion)}}</small><p v-if="note.Detalle">{{note.Detalle}}</p></span></label><div class="agenda-note-actions"><button type="button" @click="edit(note)" :disabled="saving" aria-label="Editar nota">✎</button><button type="button" @click="remove(note)" :disabled="saving" aria-label="Quitar nota">×</button></div></article>
   <details v-if="completed.length" :open="filter==='todas'" class="agenda-completed"><summary>{{completed.length}} {{completed.length===1?'tarea completada':'tareas completadas'}}</summary><label v-for="note in completed" :key="note.Id" class="agenda-note-check done"><input type="checkbox" checked :disabled="saving||note.Repeticion!=='ninguna'" @change="change(note,'reabrir')" :aria-label="'Volver a pendiente: '+note.Titulo"><s>{{note.Titulo}}</s></label></details>
  </div><footer><div class="agenda-colors"><span>Color de agenda</span><button v-for="color in colors" :key="color.id" type="button" :style="{background:color.main}" :aria-label="'Color '+color.name" :title="color.name" :aria-pressed="theme===color.id?'true':'false'" @click="setTheme(color.id)"><span v-if="theme===color.id" aria-hidden="true">✓</span></button></div><label><input type="checkbox" v-model="voice" @change="savePrefs"> Sonido y voz de mi agenda</label><small>Privado. Avisos mientras el sistema esté abierto.</small></footer>
 </section>
 <section v-if="notice" class="agenda-notice" role="status" aria-live="polite"><img :src="fishSource" alt="ALI, tu pececito"><div><strong>ALI · Tu agenda personal</strong><p>{{notice.Titulo}}</p><small>{{dateLabel(notice.Fecha)}} · {{Number(notice.Anticipacion)?'Aviso programado':'Es hora de tu tarea'}}</small><div class="agenda-notice-actions"><button type="button" :disabled="saving" @click="change(notice,'concluir')">✓ Ya lo hice</button><button type="button" @click="open=true">Ver diario</button><button type="button" @click="dismiss" aria-label="Cerrar aviso personal">×</button></div></div></section>
</aside></template>
<script>
import config from '@/store/config';
import {limaInput,taskMillis} from '@/utils/diario';
function blank(day){const date=limaInput(new Date(Date.now()+3600000));return {Titulo:'',Detalle:'',Recordar:false,Fecha:day?day+date.slice(10):date,Anticipacion:0,Frecuencia:15,Repeticion:'ninguna'};}
export default {data(){return {theme:'verde',colors:[{id:'verde',name:'Verde',dark:'#153d37',main:'#2d5b50',soft:'#edf4ef',line:'#cedfd5',ink:'#254d3e'},{id:'azul',name:'Azul',dark:'#17354e',main:'#32628a',soft:'#edf3fa',line:'#cdddec',ink:'#254a69'},{id:'violeta',name:'Violeta',dark:'#35264e',main:'#6b4f8b',soft:'#f3eef8',line:'#dfd4ea',ink:'#54406e'},{id:'rosa',name:'Rosa',dark:'#502b3b',main:'#925d78',soft:'#faf0f5',line:'#ead4df',ink:'#70435a'},{id:'ambar',name:'Ámbar',dark:'#4c3621',main:'#946b37',soft:'#faf5e9',line:'#e8dcc6',ink:'#755532'},{id:'grafito',name:'Grafito',dark:'#252d36',main:'#536271',soft:'#f0f3f6',line:'#d5dce2',ink:'#3c4b59'}],dictating:'',interim:'',dictationError:'',selectedDay:limaInput().slice(0,10),context:null,open:false,items:[],limited:false,loading:false,saving:false,error:'',form:blank(limaInput().slice(0,10)),details:false,schedule:false,filter:'fecha',filters:[{id:'fecha',text:'Del día'},{id:'pendientes',text:'Pendientes'},{id:'todas',text:'Todas'}],notice:null,voice:true,unlocked:false,dragging:false,x:0,y:220,docked:true,width:window.innerWidth,height:window.innerHeight}},computed:{themeStyle(){const c=this.colors.find(c=>c.id===this.theme)||this.colors[0];return {'--agenda-dark':c.dark,'--agenda-main':c.main,'--agenda-soft':c.soft,'--agenda-line':c.line,'--agenda-ink':c.ink};},bulbStyle(){return {left:this.x+'px',top:this.y+'px'};},panelStyle(){return {right:'12px',top:Math.min(90,Math.max(8,this.height-420))+'px',width:Math.min(380,this.width-24)+'px',maxHeight:Math.max(250,this.height-110)+'px'};},pending(){return this.items.filter(t=>t.Estado==='pendiente');},selectedDayLabel(){if(!/^\d{4}-\d{2}-\d{2}$/.test(this.selectedDay))return 'Elige una fecha';return new Intl.DateTimeFormat('es-PE',{timeZone:'America/Lima',weekday:'long',day:'numeric',month:'long',year:'numeric'}).format(new Date(this.selectedDay+'T12:00:00-05:00'));},dayPending(){return this.pending.filter(t=>t.Fecha.slice(0,10)===this.selectedDay).length;},completed(){return this.items.filter(t=>t.Estado==='concluida'&&(this.filter!=='fecha'||t.Fecha.slice(0,10)===this.selectedDay)).sort((a,b)=>Number(b.Id)-Number(a.Id));},visible(){return this.pending.filter(t=>this.filter!=='fecha'||t.Fecha.slice(0,10)===this.selectedDay).sort((a,b)=>a.Fecha.localeCompare(b.Fecha)||Number(a.Id)-Number(b.Id));},fishSource(){return require('../../static/images/ali-goldfish-talking.svg');}},
 watch:{selectedDay(day){if(/^\d{4}-\d{2}-\d{2}$/.test(day)){this.stopDictation();this.filter='fecha';this.form.Fecha=day+(this.form.Fecha||blank(day).Fecha).slice(10);}},open(value){if(!value)this.stopDictation();},details(value){if(!value&&this.dictating==='Detalle')this.stopDictation();}},
 mounted(){this.x=Math.max(0,window.innerWidth-42);this._move=e=>this.moveDrag(e);this._end=e=>this.endDrag(e);this._resize=()=>this.clamp();this._focus=()=>this.poll();this._gesture=()=>{this.unlocked=true;};this._urgent=()=>{this.stopDictation();this._supportUntil=Date.now()+12000;if(this._utterance&&window.speechSynthesis){window.speechSynthesis.cancel();this._utterance=null;}};window.addEventListener('pointermove',this._move,{passive:false});window.addEventListener('pointerup',this._end);window.addEventListener('pointercancel',this._end);window.addEventListener('resize',this._resize);window.addEventListener('focus',this._focus);window.addEventListener('pointerdown',this._gesture);window.addEventListener('support:urgent-alert',this._urgent);this.$root.$on('diario:changed',this.load);this.init();},
 beforeDestroy(){this.stopDictation();clearInterval(this._timer);clearTimeout(this._noticeTimer);clearTimeout(this._voiceTimer);window.removeEventListener('pointermove',this._move);window.removeEventListener('pointerup',this._end);window.removeEventListener('pointercancel',this._end);window.removeEventListener('resize',this._resize);window.removeEventListener('focus',this._focus);window.removeEventListener('pointerdown',this._gesture);window.removeEventListener('support:urgent-alert',this._urgent);this.$root.$off('diario:changed',this.load);if(this._utterance&&window.speechSynthesis)window.speechSynthesis.cancel();if(this._audio)this._audio.close();},methods:{
 appendDictation(field,text){const limit=field==='Titulo'?180:5000;this.form[field]=(this.form[field]+' '+text.trim()).trim().slice(0,limit);},
 stopDictation(){const speech=this._recognition;if(this.dictating&&this.interim)this.appendDictation(this.dictating,this.interim);this._recognition=null;this.dictating='';this.interim='';if(speech){speech.onresult=null;speech.onend=null;speech.onerror=null;try{speech.abort();}catch(e){}}this.$root.$emit('diario:dictation',false);},
 dictate(field){if(this.dictating===field){this.stopDictation();return;}this.stopDictation();this.dictationError='';const API=window.SpeechRecognition||window.webkitSpeechRecognition;if(!API){this.dictationError='Este navegador no admite dictado. Puedes escribir o usar Chrome con permiso de micrófono.';return;}if(this._utterance&&window.speechSynthesis){window.speechSynthesis.cancel();this._utterance=null;}const speech=new API();this._recognition=speech;this.dictating=field;this.interim='';this.$root.$emit('diario:dictation',true);speech.lang='es-PE';speech.continuous=true;speech.interimResults=true;const seen=new Set();speech.onresult=event=>{if(this._recognition!==speech)return;this.interim='';for(let i=event.resultIndex;i<event.results.length;i++){const result=event.results[i];if(result.isFinal){if(!seen.has(i)){seen.add(i);this.appendDictation(field,result[0].transcript);}}else this.interim+=result[0].transcript;}};speech.onerror=event=>{if(this._recognition!==speech)return;this.dictationError=['not-allowed','service-not-allowed'].includes(event.error)?'Permite el acceso al micrófono para dictar. El texto escrito se conserva.':event.error==='no-speech'?'No se detectó voz. Pulsa el micrófono para intentarlo otra vez.':'Se detuvo el dictado. Revisa el micrófono o la conexión y vuelve a intentarlo.';this.stopDictation();};speech.onend=()=>{if(this._recognition===speech)this.stopDictation();};try{speech.start();}catch(e){this.dictationError='No se pudo abrir el micrófono. Detén otros dictados e inténtalo nuevamente.';this.stopDictation();}},
 moveDay(step){if(!/^\d{4}-\d{2}-\d{2}$/.test(this.selectedDay))return;const date=new Date(this.selectedDay+'T12:00:00Z');date.setUTCDate(date.getUTCDate()+step);this.selectedDay=date.toISOString().slice(0,10);this.filter='fecha';},goToday(){this.selectedDay=limaInput().slice(0,10);this.filter='fecha';},
 async request(path,body){const r=await this.axios({url:config.API+'agenda/'+path,method:body?'POST':'GET',data:body,headers:this.context?{'X-Agenda-CSRF':this.context.csrf}:{},timeout:12000});return r.data;},
 async init(){try{this.context=await this.request('contexto');try{const p=JSON.parse(localStorage.getItem('agenda:prefs:'+this.context.user)||'{}');this.voice=p.voice!==false;if(this.colors.some(c=>c.id===p.theme))this.theme=p.theme;this.docked=p.docked!==false;if(Number.isFinite(p.x)&&Number.isFinite(p.y)){this.x=p.x;this.y=p.y;}}catch(e){}this.clamp();await this.load();this._timer=setInterval(()=>this.poll(),15000);this.poll();}catch(e){this.context=null;}},
 message(e){return e.response&&e.response.data&&e.response.data.error||'No se pudo guardar. Tu texto sigue aquí; vuelve a intentarlo.';},
 async load(){if(!this.context)return;this.loading=true;try{const r=await this.request('notas');this.items=r.notas;this.limited=r.limitado;}catch(e){this.error=this.message(e);}finally{this.loading=false;}},
 toggle(){if(Date.now()<(this._suppressUntil||0))return;this.open=!this.open;if(this.open)this.load();},dock(){this.docked=true;this.clamp();this.savePrefs();},
 clamp(){this.width=window.innerWidth;this.height=window.innerHeight;this.x=this.docked?Math.max(0,this.width-42):Math.min(Math.max(0,this.x),Math.max(0,this.width-42));this.y=Math.min(Math.max(8,this.y),Math.max(8,this.height-64));},
 setTheme(id){if(this.colors.some(c=>c.id===id)){this.theme=id;this.savePrefs();}},
 savePrefs(){if(this.context)try{localStorage.setItem('agenda:prefs:'+this.context.user,JSON.stringify({x:this.x,y:this.y,docked:this.docked,voice:this.voice,theme:this.theme}));}catch(e){}},
 startDrag(e){if(e.button!==0)return;this._drag={id:e.pointerId,startX:e.clientX,startY:e.clientY,x:this.x,y:this.y,target:e.currentTarget};},
 moveDrag(e){const d=this._drag;if(!d||d.id!==e.pointerId)return;const dx=e.clientX-d.startX,dy=e.clientY-d.startY;if(!this.dragging&&Math.hypot(dx,dy)<6)return;this.dragging=true;this.docked=false;e.preventDefault();try{d.target.setPointerCapture(e.pointerId);}catch(err){}this.x=d.x+dx;this.y=d.y+dy;this.clamp();},
 endDrag(e){const d=this._drag;if(!d||d.id!==e.pointerId)return;if(this.dragging){this._suppressUntil=Date.now()+350;this.docked=this.x>this.width-90;this.clamp();this.savePrefs();}try{if(d.target.hasPointerCapture(e.pointerId))d.target.releasePointerCapture(e.pointerId);}catch(err){}this.dragging=false;this._drag=null;},
 reset(){this.stopDictation();this.dictationError='';this.form=blank(this.selectedDay);this.details=false;this.schedule=false;},edit(t){this.stopDictation();this.dictationError='';this.form=Object.assign({},t,{Recordar:!!Number(t.Recordar),Fecha:t.Fecha.slice(0,16).replace(' ','T')});this.selectedDay=t.Fecha.slice(0,10);this.details=!!t.Detalle;this.schedule=!!Number(t.Recordar);this.error='';this.open=true;this.$nextTick(()=>{if(this.$refs.title)this.$refs.title.focus();});},
 async save(){if(this.saving||this.dictating)return;if(!/^\d{4}-\d{2}-\d{2}$/.test(this.selectedDay)){this.error='Elige una fecha para tu tarea.';return;}this.saving=true;this.error='';try{await this.request('notas'+(this.form.Id?'/'+this.form.Id:''),Object.assign({},this.form,{accion:'editar'}));this.reset();await this.load();this.poll();}catch(e){this.error=this.message(e);}finally{this.saving=false;}},
 async change(t,accion){if(this.saving)return;this.saving=true;this.error='';try{await this.request('notas/'+t.Id,{accion,Version:Number(t.Version)});if(this.notice&&this.notice.Id===t.Id)this.dismiss();await this.load();}catch(e){this.error=this.message(e);this.open=true;await this.load();}finally{this.saving=false;}},remove(t){if(window.confirm('¿Quitar esta nota de tu diario personal?'))this.change(t,'cancelar');},
 dateLabel(value){return new Intl.DateTimeFormat('es-PE',{timeZone:'America/Lima',day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'}).format(new Date(taskMillis(value)));},repeatLabel(value){return value==='diaria'?'Cada día':'Cada semana';},
 dismiss(){clearTimeout(this._noticeTimer);clearTimeout(this._voiceTimer);this.notice=null;},
 async poll(){if(!this.context||this._polling||document.hidden)return;this._polling=true;try{const r=await this.request('avisos');if(this.notice&&!r.notas.some(t=>t.Id===this.notice.Id))this.dismiss();const now=taskMillis(r.ahora);for(const t of r.notas){const phase=now>=taskMillis(t.Fecha)?'hora':'antes';const key='agenda:aviso:'+this.context.user+':'+t.Id+':'+t.Version+':'+phase;const announce=()=>{let last=0;try{last=Number(localStorage.getItem(key))||0;}catch(e){}if(now-last<Number(t.Frecuencia)*60000)return false;try{localStorage.setItem(key,String(now));}catch(e){}this.notice=t;clearTimeout(this._noticeTimer);this._noticeTimer=setTimeout(()=>this.dismiss(),20000);this.speak(t);return true;};const shown=navigator.locks&&navigator.locks.request?await navigator.locks.request(key,announce):announce();if(shown)break;}}catch(e){}finally{this._polling=false;}},
 speak(t,attempt=0){if(this.dictating||!this.voice||!this.unlocked||document.hidden||!this.notice||this.notice.Id!==t.Id)return;const synth=window.speechSynthesis;const host=document.querySelector('.ali-host'),ali=host&&host.__vue__;if(Date.now()<(this._supportUntil||0)||(synth&&(synth.speaking||synth.pending))||(ali&&(ali.busy||ali.listening||ali._recognition))){if(attempt<7){clearTimeout(this._voiceTimer);this._voiceTimer=setTimeout(()=>this.speak(t,attempt+1),2000);}return;}try{const Audio=window.AudioContext||window.webkitAudioContext;if(Audio){if(!this._audio)this._audio=new Audio();if(this._audio.state==='suspended')this._audio.resume();if(this._audio.state==='running'){const o=this._audio.createOscillator(),g=this._audio.createGain();o.frequency.value=660;g.gain.setValueAtTime(.045,this._audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,this._audio.currentTime+.18);o.connect(g);g.connect(this._audio.destination);o.start();o.stop(this._audio.currentTime+.18);}}}catch(e){}if(!synth||!window.SpeechSynthesisUtterance)return;const u=new window.SpeechSynthesisUtterance('Tu agenda personal te recuerda: '+t.Titulo);u.lang='es-PE';u.voice=synth.getVoices().find(v=>/^es/i.test(v.lang))||null;u.onend=u.onerror=()=>{if(this._utterance===u)this._utterance=null;};this._utterance=u;synth.speak(u);}
}};
</script>
